<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { adminT } from '../platform/admin-i18n'
import '../platform/i18n-batch-b'
import { getB6AccessibilityChecklist, getB6ObservabilityDashboard, getB6PerformanceBudget, getB6ReleaseMatrix, getB6ResponsiveChecklist } from '../api/b6'
import { toDashboard, toMatrix, type B6AdminDashboard, type B6AdminMatrix } from '../domain/b6'

const loading = ref(true)
const matrix = ref<B6AdminMatrix>(toMatrix({}))
const dashboard = ref<B6AdminDashboard>(toDashboard({}))
const checklists = ref({ accessibility: 0, responsive: 0, performanceLevels: 0 })

async function load(): Promise<void> { loading.value = true; try { const [matrixResponse, dashboardResponse, performanceResponse, accessibilityResponse, responsiveResponse] = await Promise.all([getB6ReleaseMatrix(), getB6ObservabilityDashboard(), getB6PerformanceBudget(), getB6AccessibilityChecklist(), getB6ResponsiveChecklist()]); matrix.value = toMatrix(matrixResponse); dashboard.value = toDashboard(dashboardResponse); const performanceData = performanceResponse && typeof performanceResponse === 'object' && 'data' in performanceResponse && typeof performanceResponse.data === 'object' && performanceResponse.data !== null ? performanceResponse.data as Record<string, unknown> : {}; const accessibilityData = accessibilityResponse && typeof accessibilityResponse === 'object' && 'data' in accessibilityResponse && typeof accessibilityResponse.data === 'object' && accessibilityResponse.data !== null ? accessibilityResponse.data as Record<string, unknown> : {}; const responsiveData = responsiveResponse && typeof responsiveResponse === 'object' && 'data' in responsiveResponse && typeof responsiveResponse.data === 'object' && responsiveResponse.data !== null ? responsiveResponse.data as Record<string, unknown> : {}; checklists.value = { accessibility: Array.isArray(accessibilityData.checks) ? accessibilityData.checks.length : 0, responsive: Array.isArray(responsiveData.checks) ? responsiveData.checks.length : 0, performanceLevels: Array.isArray(performanceData.levels) ? performanceData.levels.length : 0 } } catch (error) { ElMessage.error(error instanceof Error ? error.message : adminT('releaseView.loadFailed')) } finally { loading.value = false } }
onMounted(() => { void load() })
</script>

<template>
  <div class="view-stack"><div class="view-intro"><div><span class="admin-header__eyebrow">B6 · RELEASE CONTROL</span><h2>{{ adminT('releaseView.heading') }}</h2><p>{{ adminT('releaseView.intro') }}</p></div><el-button :loading="loading" @click="load">{{ adminT('releaseView.refreshEvidence') }}</el-button></div>
    <el-alert :title="adminT('releaseView.failClosed')" type="warning" :closable="false" show-icon />
    <el-row :gutter="16"><el-col :span="6"><el-card shadow="never" class="metric-card"><span>{{ adminT('releaseView.statTargets') }}</span><strong>{{ matrix.targets.length }}</strong><small>{{ matrix.codeLayerStatus }}</small></el-card></el-col><el-col :span="6"><el-card shadow="never" class="metric-card"><span>{{ adminT('releaseView.statAlerts') }}</span><strong>{{ dashboard.alerts.length }}</strong><small>{{ adminT('releaseView.statAlertsNote') }}</small></el-card></el-col><el-col :span="6"><el-card shadow="never" class="metric-card"><span>{{ adminT('releaseView.statA11y') }}</span><strong>{{ checklists.accessibility }}</strong><small>{{ adminT('releaseView.statA11yNote') }}</small></el-card></el-col><el-col :span="6"><el-card shadow="never" class="metric-card"><span>{{ adminT('releaseView.statPerf') }}</span><strong>{{ checklists.performanceLevels }}</strong><small>{{ adminT('releaseView.statPerfNote') }}</small></el-card></el-col></el-row>
    <el-card shadow="never"><template #header><div class="card-header"><span>{{ adminT('releaseView.matrixTitle') }}</span><el-tag type="info" effect="plain">{{ matrix.realDeviceEvidenceStatus }}</el-tag></div></template><el-table :data="matrix.targets" stripe><el-table-column prop="platformCode" :label="adminT('releaseView.colPlatform')" width="190" /><el-table-column prop="priority" :label="adminT('releaseView.colPriority')" width="100" /><el-table-column prop="implementation" :label="adminT('releaseView.colOwner')" min-width="220" /><el-table-column prop="sharedBusinessCode" :label="adminT('releaseView.colSharedCode')" min-width="190" /><el-table-column :label="adminT('releaseView.colBuildStatus')" width="150"><template #default="scope"><el-tag :type="scope.row.buildStatus === 'READY' ? 'success' : 'warning'" effect="plain">{{ scope.row.buildStatus }}</el-tag></template></el-table-column><el-table-column prop="installability" :label="adminT('releaseView.colInstallEvidence')" min-width="180" /></el-table></el-card>
    <el-row :gutter="16"><el-col :span="12"><el-card shadow="never"><template #header><div class="card-header"><span>{{ adminT('releaseView.alertsTitle') }}</span><el-tag :type="dashboard.alerts.length ? 'danger' : 'success'">{{ dashboard.alerts.length ? adminT('releaseView.alertsOpen') : adminT('releaseView.alertsNone') }}</el-tag></div></template><el-empty v-if="dashboard.alerts.length === 0" :description="adminT('releaseView.alertsEmpty')" /><el-table v-else :data="dashboard.alerts" size="small"><el-table-column prop="alertCode" :label="adminT('releaseView.colAlert')" /><el-table-column prop="severity" :label="adminT('releaseView.colSeverity')" /><el-table-column prop="errorCode" :label="adminT('releaseView.colErrorCode')" /></el-table></el-card></el-col><el-col :span="12"><el-card shadow="never"><template #header><span>{{ adminT('releaseView.correlationTitle') }}</span></template><div class="b6-admin-chip-list"><el-tag v-for="field in dashboard.correlationFields" :key="field" effect="plain">{{ field }}</el-tag></div><p class="b6-admin-note">{{ adminT('releaseView.correlationNote') }}</p></el-card></el-col></el-row>
  </div>
</template>
